134	function parseCodexHooksDocument(content: string): CodexHooksDocument {
135	  let parsed: unknown;
136	  try {
137	    parsed = JSON.parse(content);
138	  } catch {
139	    return {
140	      hooks: {
141	        SessionStart: ensureHookEventGroup([]),
142	        UserPromptSubmit: ensureHookEventGroup([]),
143	        PreToolUse: ensureHookEventGroup([]),
144	        PostToolUse: ensureHookEventGroup([]),
145	        Stop: ensureHookEventGroup([]),
146	      },
147	    };
148	  }
149	  const root = isRecord(parsed) ? parsed : {};
150	  const hooksRecord = isRecord(root["hooks"]) ? root["hooks"] : {};
151	  return {
152	    hooks: {
153	      SessionStart: ensureHookEventGroup(parseHookGroups(hooksRecord["SessionStart"])),
154	      UserPromptSubmit: ensureHookEventGroup(parseHookGroups(hooksRecord["UserPromptSubmit"])),
155	      PreToolUse: ensureHookEventGroup(parseHookGroups(hooksRecord["PreToolUse"])),
156	      PostToolUse: ensureHookEventGroup(parseHookGroups(hooksRecord["PostToolUse"])),
157	      Stop: ensureHookEventGroup(parseHookGroups(hooksRecord["Stop"])),
158	    },
