162	function sessionResumeId(line: CodexSessionLine): string | null {
163	  if (typeof line.threadId === "string" && line.threadId) {
164	    return line.threadId;
165	  }
166	  if (line.type === "session_meta" && typeof line.payload?.id === "string" && line.payload.id) {
167	    return line.payload.id;
168	  }
169	  return null;
