172	export async function collectJsonlFiles(dir: string, depth = 0): Promise<string[]> {
173	  if (depth > MAX_SESSION_SCAN_DEPTH) {
174	    return [];
175	  }
176	
177	  let entries: string[];
178	  try {
179	    entries = await readdir(dir);
180	  } catch {
181	    return [];
182	  }
183	
184	  const files: string[] = [];
185	  for (const entry of entries) {
186	    const filePath = join(dir, entry);
187	    if (entry.endsWith(".jsonl")) {
188	      files.push(filePath);
189	      continue;
190	    }
191	    try {
192	      if ((await lstat(filePath)).isDirectory()) {
193	        files.push(...(await collectJsonlFiles(filePath, depth + 1)));
194	      }
195	    } catch {
196	      // Ignore inaccessible entries.
197	    }
198	  }
199	  return files;
200	}
201	
202	async function readSessionMeta(
203	  filePath: string,
204	): Promise<{ cwd: string; threadId: string | null } | null> {
205	  try {
206	    const input = createReadStream(filePath, { encoding: "utf-8" });
207	    const reader = createInterface({ input, crlfDelay: Infinity });
208	    let linesRead = 0;
209	    let threadId: string | null = null;
210	    for await (const line of reader) {
211	      if (linesRead >= 10) {
212	        break;
213	      }
214	      linesRead += 1;
215	      const trimmed = line.trim();
216	      if (!trimmed) continue;
217	      try {
218	        const parsed = JSON.parse(trimmed) as CodexSessionLine;
219	        const cwd = sessionMetaCwd(parsed);
220	        const resumeId = sessionResumeId(parsed);
221	        if (resumeId && !threadId) {
222	          threadId = resumeId;
223	        }
224	        if (cwd) {
225	          return { cwd, threadId };
226	        }
227	      } catch {
228	        // Ignore malformed lines and keep scanning the file header.
229	      }
230	    }
231	  } catch {
232	    return null;
233	  }
234	  return null;
235	}
236	
237	async function loadSessionIndexForRoot(
238	  sessionRootDir: string,
239	): Promise<Map<string, IndexedSessionFile>> {
240	  const now = Date.now();
241	  if (
242	    sessionRootDir === CODEX_SESSIONS_DIR &&
243	    sessionIndexCache &&
244	    sessionIndexCache.expiresAt > now
245	  ) {
246	    return sessionIndexCache.byCwd;
247	  }
248	
249	  const files = await collectJsonlFiles(sessionRootDir);
250	  const byCwd = new Map<string, IndexedSessionFile>();
251	
252	  for (const filePath of files) {
253	    const meta = await readSessionMeta(filePath);
254	    if (!meta) {
255	      continue;
256	    }
257	    try {
258	      const fileStat = await stat(filePath);
259	      const existing = byCwd.get(meta.cwd);
260	      if (!existing || fileStat.mtimeMs > existing.mtimeMs) {
261	        byCwd.set(meta.cwd, {
262	          path: filePath,
263	          mtimeMs: fileStat.mtimeMs,
264	          threadId: meta.threadId,
265	        });
266	      }
267	    } catch {
268	      // Ignore unreadable files.
269	    }
270	  }
271	
272	  if (sessionRootDir === CODEX_SESSIONS_DIR) {
273	    sessionIndexCache = {
274	      expiresAt: now + SESSION_INDEX_TTL_MS,
275	      byCwd,
276	    };
277	  }
278	  return byCwd;
279	}
280	
281	function resolveSessionRootDirs(options?: {
282	  sessionRootDir?: string;
283	  sessionRootDirs?: string[];
284	}): string[] {
285	  const roots = [
286	    ...(options?.sessionRootDirs ?? []),
287	    ...(options?.sessionRootDir ? [options.sessionRootDir] : []),
288	    CODEX_SESSIONS_DIR,
289	  ];
290	  return [...new Set(roots.filter(Boolean))];
291	}
292	
293	async function readThreadId(filePath: string): Promise<string | null> {
294	  try {
295	    const input = createReadStream(filePath, { encoding: "utf-8" });
296	    const reader = createInterface({ input, crlfDelay: Infinity });
297	    for await (const line of reader) {
298	      const trimmed = line.trim();
299	      if (!trimmed) continue;
300	      try {
301	        const parsed = JSON.parse(trimmed) as CodexSessionLine;
302	        const resumeId = sessionResumeId(parsed);
303	        if (resumeId) {
304	          return resumeId;
305	        }
306	      } catch {
307	        // Ignore malformed lines.
308	      }
309	    }
310	  } catch {
311	    return null;
312	  }
313	  return null;
314	}
315	
316	export async function findCodexSessionId(
317	  worktreePath: string,
318	  options?: { sessionRootDir?: string; sessionRootDirs?: string[] },
319	): Promise<string | null> {
320	  const candidates = await resolveWorktreePathCandidates(worktreePath);
321	  for (const sessionRootDir of resolveSessionRootDirs(options)) {
322	    const sessionIndex = await loadSessionIndexForRoot(sessionRootDir);
323	    let bestMatch: IndexedSessionFile | null = null;
324	    for (const candidate of candidates) {
325	      const match = sessionIndex.get(candidate);
326	      if (match && (!bestMatch || match.mtimeMs > bestMatch.mtimeMs)) {
327	        bestMatch = match;
328	      }
329	    }
330	    if (!bestMatch) {
331	      continue;
332	    }
333	    return bestMatch.threadId ?? readThreadId(bestMatch.path);
334	  }
335	  return null;
336	}
337	
338	function withCodexHome(command: string, codexHomePath: string | undefined): string {
339	  if (!codexHomePath) {
340	    return command;
341	  }
342	  return `CODEX_HOME=${shellEscape(codexHomePath)} ${command}`;
343	}
344	
345	function appendCodexArgs(command: string, codexArgs: string[] | undefined): string {
346	  if (!codexArgs || codexArgs.length === 0) {
347	    return command;
348	  }
349	  return `${command} ${codexArgs.map((arg) => shellEscape(arg)).join(" ")}`;
350	}
351	
352	export function buildCodexPlan(
353	  prompt: string,
354	  options?: { codexHomePath?: string; codexArgs?: string[] },
355	): AgentLaunchPlan {
356	  return {
357	    launchCommand: withCodexHome(
358	      appendCodexArgs(
359	        `${codexCommand()} --enable codex_hooks --dangerously-bypass-approvals-and-sandbox`,
360	        options?.codexArgs,
361	      ),
362	      options?.codexHomePath,
363	    ),
364	    initialMessage: prompt,
365	    readyMarkers: ["OpenAI Codex", "›"],
366	  };
367	}
368	
369	export function buildCodexResumePlan(
370	  threadId: string,
371	  binary = codexCommand(),
372	  options?: { codexHomePath?: string; codexArgs?: string[] },
373	): AgentResumePlan {
374	  return {
375	    launchCommand: withCodexHome(
376	      appendCodexArgs(
377	        `${shellEscape(binary)} resume --enable codex_hooks --dangerously-bypass-approvals-and-sandbox ${shellEscape(threadId)}`,
378	        options?.codexArgs,
379	      ),
380	      options?.codexHomePath,
381	    ),
382	    readyMarkers: ["›"],
383	  };
384	}
385	
386	export async function buildCodexRestorePlan(
387	  worktreePath: string,
388	  prompt: string,
389	  options?: { codexHomePath?: string; codexArgs?: string[] },
390	): Promise<AgentLaunchPlan | null> {
391	  const sessionRootDir = options?.codexHomePath
392	    ? join(options.codexHomePath, "sessions")
393	    : undefined;
394	  const threadId = await findCodexSessionId(
395	    worktreePath,
396	    sessionRootDir ? { sessionRootDirs: [sessionRootDir, CODEX_SESSIONS_DIR] } : undefined,
397	  );
398	  if (!threadId) {
399	    return null;
400	  }
401	
402	  return {
403	    ...buildCodexResumePlan(threadId, codexCommand(), options),
404	    initialMessage: prompt,
405	  };
406	}
407	
408	export function codexHookHomePath(sessionToolDir: string): string {
409	  return join(sessionToolDir, CODEX_HOME_DIR);
410	}
411	
412	export async function ensureCodexHooksConfig(sessionToolDir: string): Promise<string> {
413	  const codexDir = codexHookHomePath(sessionToolDir);
414	  const hooksPath = join(codexDir, CODEX_HOOKS_FILE);
415	  await mkdir(codexDir, { recursive: true });
416	  const existingContent = await readFile(hooksPath, "utf8").catch(() => "");
417	  const next = parseCodexHooksDocument(existingContent);
418	  const userConfigPath = join(homedir(), ".codex", "config.toml");
419	  const sessionConfigPath = join(codexDir, "config.toml");
420	  const baseConfig = await readFile(userConfigPath, "utf8").catch(() => "");
421	  const suppressWarningConfig = baseConfig.includes("suppress_unstable_features_warning")
422	    ? baseConfig
423	    : `${baseConfig.trimEnd()}\n${baseConfig.trimEnd() ? "\n" : ""}suppress_unstable_features_warning = true\n`;
424	  await writeFile(sessionConfigPath, suppressWarningConfig, "utf8");
425	  const userAgentsDir = join(homedir(), ".codex", "agents");
426	  if (existsSync(userAgentsDir)) {
427	    await cp(userAgentsDir, join(codexDir, "agents"), { recursive: true, force: true });
428	  }
429	  await writeFile(hooksPath, JSON.stringify(next, null, 2) + "\n", "utf8");
430	  return codexDir;
431	}
432	
433	export type RolloutBaseline = Map<string, number>;
434	
435	export async function captureCodexRolloutBaseline(sessionsDir: string): Promise<RolloutBaseline> {
436	  const baseline: RolloutBaseline = new Map();
437	  let files: string[];
438	  try {
439	    files = await collectJsonlFiles(sessionsDir);
440	  } catch {
441	    return baseline;
442	  }
443	  for (const filePath of files) {
444	    try {
445	      const fileStat = await stat(filePath);
446	      baseline.set(filePath, fileStat.size);
447	    } catch {
448	      // Ignore inaccessible files.
449	    }
450	  }
451	  return baseline;
452	}
453	
454	interface RolloutResponseItemPayload {
455	  type?: string;
456	  role?: string;
457	  content?: Array<{ type?: string; text?: string }>;
458	}
459	
460	interface RolloutEventMsgPayload {
461	  type?: string;
462	  message?: string;
463	}
464	
465	function extractUserTextFromLine(line: string): string | null {
466	  let parsed: unknown;
467	  try {
468	    parsed = JSON.parse(line);
469	  } catch {
470	    return null;
471	  }
472	  if (!isRecord(parsed)) {
473	    return null;
474	  }
475	  const type = parsed["type"];
476	  const payload = parsed["payload"];
477	  if (!isRecord(payload)) {
478	    return null;
479	  }
480	
481	  if (type === "response_item") {
482	    const p = payload as unknown as RolloutResponseItemPayload;
483	    if (p.type === "message" && p.role === "user" && Array.isArray(p.content)) {
484	      const texts = p.content
485	        .filter(
486	          (c): c is { type: string; text: string } =>
487	            isRecord(c) && c.type === "input_text" && typeof c.text === "string",
488	        )
489	        .map((c) => c.text);
490	      return texts.length > 0 ? texts.join("") : null;
491	    }
492	  }
493	
494	  if (type === "event_msg") {
495	    const p = payload as unknown as RolloutEventMsgPayload;
496	    if (p.type === "user_message" && typeof p.message === "string") {
497	      return p.message;
498	    }
499	  }
500	
501	  return null;
502	}
503	
504	export async function scanCodexRolloutForMessage(
505	  sessionsDir: string,
506	  messageText: string,
507	  baseline: RolloutBaseline,
508	): Promise<{ found: boolean; lastScannedFile: string | null }> {
509	  let files: string[];
510	  try {
511	    files = await collectJsonlFiles(sessionsDir);
512	  } catch {
513	    return { found: false, lastScannedFile: null };
514	  }
515	  let lastScannedFile: string | null = null;
516	  const trimmedTarget = messageText.trim();
517	  for (const filePath of files) {
518	    lastScannedFile = filePath;
519	    const offset = baseline.get(filePath) ?? 0;
520	    try {
521	      const input = createReadStream(filePath, { encoding: "utf-8", start: offset });
522	      const reader = createInterface({ input, crlfDelay: Infinity });
523	      try {
524	        for await (const rawLine of reader) {
525	          const trimmedLine = rawLine.trim();
526	          if (!trimmedLine) continue;
527	          const extracted = extractUserTextFromLine(trimmedLine);
528	          if (extracted !== null && extracted.trim() === trimmedTarget) {
529	            reader.close();
530	            return { found: true, lastScannedFile: filePath };
531	          }
532	        }
533	      } finally {
534	        reader.close();
535	      }
536	    } catch {
537	      // Ignore unreadable files.
538	    }
539	  }
540	  return { found: false, lastScannedFile };
541	}
