338	function parseSidecars(projectId: string, value: unknown): Record<string, SidecarConfig> {
339	  if (value === undefined) return {};
340	  const label = `projects.${projectId}.sidecars`;
341	  const raw = asObject(value, label);
342	  const result: Record<string, SidecarConfig> = {};
343	  for (const [name, entry] of Object.entries(raw)) {
344	    if (!VALID_ID_RE.test(name)) {
345	      throw new Error(
346	        `${label}.${name} is invalid: sidecar names must match ${VALID_ID_RE.source}`,
347	      );
348	    }
349	    const entryLabel = `${label}.${name}`;
350	    const entryRaw = asObject(entry, entryLabel);
351	    const command = asString(entryRaw["command"], `${entryLabel}.command`);
352	    const autoStart = asOptionalBoolean(entryRaw["autoStart"], `${entryLabel}.autoStart`) ?? false;
353	    const envRaw = entryRaw["env"];
354	    let env: Record<string, string> | undefined;
355	    if (envRaw !== undefined) {
356	      const envObj = asObject(envRaw, `${entryLabel}.env`);
357	      env = {};
358	      for (const [k, v] of Object.entries(envObj)) {
359	        env[k] = asString(v, `${entryLabel}.env.${k}`);
360	      }
361	    }
362	    const portsRaw = entryRaw["ports"];
363	    let ports: SidecarConfig["ports"];
364	    if (portsRaw !== undefined) {
365	      const portsObj = asObject(portsRaw, `${entryLabel}.ports`);
366	      ports = {};
367	      for (const [portId, portValue] of Object.entries(portsObj)) {
368	        if (!VALID_ID_RE.test(portId)) {
369	          throw new Error(
370	            `${entryLabel}.ports.${portId} is invalid: port ids must match ${VALID_ID_RE.source}`,
371	          );
372	        }
373	        const portLabel = `${entryLabel}.ports.${portId}`;
374	        const portObj = asObject(portValue, portLabel);
375	        const start = asPortNumber(portObj["start"], `${portLabel}.start`);
376	        const end = asPortNumber(portObj["end"], `${portLabel}.end`);
377	        if (end < start) {
378	          throw new Error(`${portLabel}.end must be greater than or equal to ${portLabel}.start`);
379	        }
380	        ports[portId] = {
381	          env: asString(portObj["env"], `${portLabel}.env`),
382	          start,
383	          end,
384	        };
385	      }
386	    }
387	    result[name] = { command, autoStart, ...(env ? { env } : {}), ...(ports ? { ports } : {}) };
388	  }
389	  return result;
390	}
