412	function parseTrigger(
413	  projectId: string,
414	  triggerId: string,
415	  value: unknown,
416	  sources: Record<string, SourceConfig>,
417	): TriggerConfig {
418	  if (!VALID_ID_RE.test(triggerId)) {
419	    throw new Error(
420	      `projects.${projectId}.triggers.${triggerId} is invalid: trigger ids must match ${VALID_ID_RE.source}`,
421	    );
422	  }
423	
424	  const label = `projects.${projectId}.triggers.${triggerId}`;
425	  const raw = asObject(value, label);
426	  const source = asString(raw["source"], `${label}.source`);
427	  const event = asString(raw["event"], `${label}.event`);
428	
429	  const sourceConfig = sources[source];
430	  if (!sourceConfig) {
431	    throw new Error(`${label}.source references unknown source "${source}"`);
432	  }
433	  const expectedEvents = expectedEventsForSource(sourceConfig);
434	  if (!expectedEvents.includes(event)) {
435	    throw new Error(
436	      `${label}.event uses unsupported event "${event}" for source "${source}"; expected one of ${expectedEvents.join(", ")}`,
437	    );
438	  }
439	
440	  const hasSpawn = raw["spawn"] !== undefined;
441	  const hasSend = raw["send"] !== undefined;
442	  if (hasSpawn === hasSend) {
443	    throw new Error(`${label} must define exactly one of "spawn" or "send"`);
444	  }
445	
446	  if (hasSend) {
447	    return { source, event, send: parseSendConfig(projectId, triggerId, raw) };
448	  }
449	
450	  const spawnRaw = asObject(raw["spawn"], `${label}.spawn`);
451	  const prompt = asString(spawnRaw["prompt"], `${label}.spawn.prompt`);
452	  const steps = asOptionalStringArray(spawnRaw["steps"], `${label}.spawn.steps`);
453	  const agent = asOptionalAgent(spawnRaw["agent"], `${label}.spawn.agent`);
454	  const branch = asOptionalString(spawnRaw["branch"], `${label}.spawn.branch`);
455	  const overrides = parseSpawnOverrides(spawnRaw["overrides"], `${label}.spawn.overrides`);
456	
457	  return {
458	    source,
459	    event,
460	    spawn: {
461	      prompt,
462	      ...(steps !== undefined ? { steps } : {}),
463	      ...(agent !== undefined ? { agent } : {}),
464	      ...(branch !== undefined ? { branch } : {}),
465	      ...(overrides !== undefined ? { overrides } : {}),
466	    },
467	  };
468	}
469	
470	function parseProject(configDir: string, projectId: string, value: unknown): ProjectConfig {
471	  if (!VALID_ID_RE.test(projectId)) {
472	    throw new Error(
473	      `projects.${projectId} is invalid: project ids must match ${VALID_ID_RE.source}`,
474	    );
475	  }
476	
477	  const label = `projects.${projectId}`;
478	  const raw = asObject(value, label);
479	  const path = resolveFrom(configDir, asString(raw["path"], `${label}.path`));
480	  const name = asOptionalString(raw["name"], `${label}.name`);
481	  const defaultBranch = asOptionalString(raw["defaultBranch"], `${label}.defaultBranch`) ?? "main";
482	  const sessionPrefix =
483	    asOptionalString(raw["sessionPrefix"], `${label}.sessionPrefix`) ?? derivePrefix(projectId);
484	  const worktree = asOptionalBoolean(raw["worktree"], `${label}.worktree`) ?? true;
485	  const symlinks = asOptionalStringArray(raw["symlinks"], `${label}.symlinks`) ?? [];
486	  const codexArgs = asOptionalStringArray(raw["codexArgs"], `${label}.codexArgs`);
487	  const spawn = parseProjectSpawn(projectId, raw["spawn"]);
488	  const preflight = parseProjectPreflight(projectId, raw["preflight"]);
489	  const devServer = parseDevServer(projectId, raw["devServer"]);
490	  const hasDevServerKey = raw["devServer"] !== undefined;
491	  const hasSidecarsKey = raw["sidecars"] !== undefined;
492	  if (hasDevServerKey && hasSidecarsKey) {
493	    throw new Error(`projects.${projectId} defines both "devServer" and "sidecars"; pick one`);
494	  }
495	  const sidecars = hasSidecarsKey
496	    ? parseSidecars(projectId, raw["sidecars"])
497	    : devServer
498	      ? parseDevServerAsSidecar(devServer)
499	      : {};
500	  const defaultAgent = asOptionalAgent(raw["defaultAgent"], `${label}.defaultAgent`);
501	  const sourcesRaw = raw["sources"] ? asObject(raw["sources"], `${label}.sources`) : {};
502	  const sources: Record<string, SourceConfig> = {};
503	  for (const [sourceId, sourceValue] of Object.entries(sourcesRaw)) {
504	    sources[sourceId] = parseSource(projectId, sourceId, sourceValue);
505	  }
506	  const triggersRaw = raw["triggers"] ? asObject(raw["triggers"], `${label}.triggers`) : {};
507	  const triggers: Record<string, TriggerConfig> = {};
508	  for (const [triggerId, triggerValue] of Object.entries(triggersRaw)) {
509	    triggers[triggerId] = parseTrigger(projectId, triggerId, triggerValue, sources);
510	  }
511	
512	  if (!VALID_ID_RE.test(sessionPrefix)) {
513	    throw new Error(`projects.${projectId}.sessionPrefix must match ${VALID_ID_RE.source}`);
514	  }
515	
516	  return {
517	    ...(name !== undefined ? { name } : {}),
518	    path,
519	    defaultBranch,
520	    sessionPrefix,
521	    worktree,
522	    symlinks,
523	    ...(codexArgs !== undefined ? { codexArgs } : {}),
524	    ...(spawn !== undefined ? { spawn } : {}),
525	    ...(preflight !== undefined ? { preflight } : {}),
526	    sidecars,
527	    ...(defaultAgent !== undefined ? { defaultAgent } : {}),
528	    sources,
529	    triggers,
530	  };
531	}
