533	function parseConfigFile(
534	  configPath: string,
535	  mode: ConfigMode,
536	  defaults?: ConfigDefaults,
537	): AppConfig {
538	  const configDir = dirname(configPath);
539	  const raw = parseYaml(readFileSync(configPath, "utf-8")) as unknown;
540	  const root = asObject(raw, "config");
541	
542	  const resolvedDefaults = defaults ?? defaultConfigDefaults(configDir);
543	  const server = root["server"] ? asObject(root["server"], "server") : {};
544	  const tmux = root["tmux"] ? asObject(root["tmux"], "tmux") : {};
545	  const ui = root["ui"] ? asObject(root["ui"], "ui") : {};
546	  const voice = root["voice"] ? asObject(root["voice"], "voice") : {};
547	  const projectsRaw =
548	    root["projects"] === undefined ? undefined : asObject(root["projects"], "projects");
549	  if (mode === "project" && projectsRaw === undefined) {
550	    throw new Error("projects must be an object");
551	  }
552	
553	  const normalizedProjects: Record<string, ProjectConfig> = {};
554	  const prefixOwners = new Map<string, string>();
555	  for (const [projectId, projectValue] of Object.entries(projectsRaw ?? {})) {
556	    const parsedProject = parseProject(configDir, projectId, projectValue);
557	    const existingOwner = prefixOwners.get(parsedProject.sessionPrefix);
558	    if (existingOwner) {
559	      throw new Error(
560	        `sessionPrefix "${parsedProject.sessionPrefix}" is duplicated in projects.${existingOwner} and projects.${projectId}`,
561	      );
562	    }
563	    prefixOwners.set(parsedProject.sessionPrefix, projectId);
564	    normalizedProjects[projectId] = parsedProject;
565	  }
566	
567	  const serverPort =
568	    mode === "instance"
569	      ? (asOptionalNumber(server["port"], "server.port") ?? resolvedDefaults.serverPort)
570	      : resolvedDefaults.serverPort;
571	
572	  return {
573	    configPath,
574	    server: {
575	      host:
576	        mode === "instance"
577	          ? (asOptionalString(server["host"], "server.host") ?? resolvedDefaults.serverHost)
578	          : resolvedDefaults.serverHost,
579	      port: serverPort,
580	    },
581	    dataDir:
582	      mode === "instance"
583	        ? resolveFrom(
584	            configDir,
585	            asOptionalString(root["dataDir"], "dataDir") ?? resolvedDefaults.dataDir,
586	          )
587	        : resolvedDefaults.dataDir,
588	    worktreeDir:
589	      mode === "instance"
590	        ? resolveFrom(
591	            configDir,
592	            asOptionalString(root["worktreeDir"], "worktreeDir") ?? resolvedDefaults.worktreeDir,
593	          )
594	        : resolvedDefaults.worktreeDir,
595	    defaultAgent:
596	      mode === "instance"
597	        ? (asOptionalAgent(root["defaultAgent"], "defaultAgent") ?? resolvedDefaults.defaultAgent)
598	        : resolvedDefaults.defaultAgent,
599	    tmux: {
600	      socketName:
601	        mode === "instance"
602	          ? (asOptionalString(tmux["socketName"], "tmux.socketName") ??
603	            defaultTmuxSocketName(serverPort))
604	          : resolvedDefaults.tmuxSocketName,
605	    },
606	    ui: {
607	      port:
608	        mode === "instance"
609	          ? (asOptionalNumber(ui["port"], "ui.port") ?? resolvedDefaults.uiPort)
610	          : resolvedDefaults.uiPort,
611	    },
612	    voice: (() => {
613	      const provider =
614	        mode === "instance"
615	          ? (asOptionalVoiceProvider(voice["provider"], "voice.provider") ??
616	            resolvedDefaults.voiceProvider)
617	          : resolvedDefaults.voiceProvider;
618	      const model =
619	        mode === "instance"
620	          ? (asOptionalString(voice["model"], "voice.model") ?? resolvedDefaults.voiceModel)
621	          : resolvedDefaults.voiceModel;
622	      const configuredModelPath =
623	        mode === "instance"
624	          ? asOptionalString(voice["modelPath"], "voice.modelPath")
625	          : asOptionalString(voice["modelPath"], "voice.modelPath");
626	      const modelPath = configuredModelPath
627	        ? resolveFrom(configDir, configuredModelPath)
628	        : undefined;
629	
630	      return {
631	        provider,
632	        language:
633	          mode === "instance"
634	            ? (asOptionalString(voice["language"], "voice.language") ??
635	              resolvedDefaults.voiceLanguage)
636	            : resolvedDefaults.voiceLanguage,
637	        model,
638	        ...(modelPath !== undefined ? { modelPath } : {}),
639	      };
640	    })(),
641	    projects: normalizedProjects,
642	  };
643	}
