645	function findConfigUpwards(startDir: string, filenames: readonly string[]): string | undefined {
646	  let current = resolve(startDir);
647	  for (;;) {
648	    for (const filename of filenames) {
649	      const candidate = join(current, filename);
650	      if (existsSync(candidate)) {
651	        return candidate;
652	      }
653	    }
654	    const parent = dirname(current);
655	    if (parent === current) {
656	      return undefined;
657	    }
658	    current = parent;
659	  }
660	}
